document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('root');
  root.innerHTML = App();

  /* Category filter */
  root.addEventListener('click', (e) => {
    const chip = e.target.closest('.cat-chip');
    if (chip) {
      document.querySelectorAll('.cat-chip').forEach(c => c.setAttribute('aria-pressed', 'false'));
      chip.setAttribute('aria-pressed', 'true');
    }

    /* Wishlist toggle */
    const wishBtn = e.target.closest('.product-wishlist');
    if (wishBtn) {
      const pressed = wishBtn.getAttribute('aria-pressed') === 'true';
      wishBtn.setAttribute('aria-pressed', String(!pressed));
      const name = wishBtn.getAttribute('aria-label');
      wishBtn.setAttribute('aria-label',
        !pressed
          ? name.replace('Add', 'Remove')
          : name.replace('Remove', 'Add')
      );
    }

    /* Add to cart feedback */
    const cartBtn = e.target.closest('.add-to-cart');
    if (cartBtn) {
      const original = cartBtn.textContent;
      cartBtn.textContent = 'Added ✓';
      cartBtn.style.background = 'var(--accent)';
      cartBtn.style.color = '#000';
      cartBtn.style.borderColor = 'var(--accent)';
      setTimeout(() => {
        cartBtn.textContent = original;
        cartBtn.style.cssText = '';
      }, 1800);
      /* update cart count */
      const badge = document.querySelector('#cart-btn .badge');
      if (badge) {
        const n = parseInt(badge.textContent, 10) + 1;
        badge.textContent = n;
        document.querySelector('#cart-btn').setAttribute('aria-label', `Shopping bag, ${n} items`);
      }
    }

    /* Newsletter form */
    const form = e.target.closest('.newsletter-form');
    if (form && e.target.type === 'submit') {
      e.preventDefault();
      const input = form.querySelector('input[type="email"]');
      if (input.value && input.checkValidity()) {
        input.value = '';
        const btn = form.querySelector('button');
        const original = btn.textContent;
        btn.textContent = 'You\'re in! 🎉';
        btn.disabled = true;
        setTimeout(() => {
          btn.textContent = original;
          btn.disabled = false;
        }, 3000);
      } else {
        input.focus();
      }
    }
  });

  /* Countdown timer */
  let endTime = Date.now() + (8 * 3600 + 42 * 60 + 17) * 1000;
  const tick = () => {
    const diff = Math.max(0, endTime - Date.now());
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const pad = n => String(n).padStart(2, '0');
    const hEl = document.getElementById('cd-h');
    const mEl = document.getElementById('cd-m');
    const sEl = document.getElementById('cd-s');
    if (hEl) hEl.textContent = pad(h);
    if (mEl) mEl.textContent = pad(m);
    if (sEl) sEl.textContent = pad(s);
  };
  tick();
  setInterval(tick, 1000);

  /* Intersection observer for animate-in */
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.animationPlayState = 'running';
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });
    document.querySelectorAll('.animate-in').forEach(el => {
      el.style.animationPlayState = 'paused';
      io.observe(el);
    });
  }
});
