/* ── Reset & base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0f;
  --surface:   #17171b;
  --surface-2: #222228;
  --border:    #2e2e38;
  --accent:    #e8c547;
  --accent-2:  #e05c5c;
  --text:      #f0f0f4;
  --muted:     #8888a0;
  --radius:    12px;
  --transition: 220ms ease;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; }

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px; left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: #000;
  padding: .5rem 1.25rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 700;
  z-index: 9999;
  white-space: nowrap;
}
.skip-link:focus { top: 0; }

/* ── Focus ring ───────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Layout helpers ───────────────────────────────────────── */
.container {
  width: min(1200px, 100%);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

section { padding-block: 4rem; }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-title {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.section-link {
  font-size: .85rem;
  color: var(--accent);
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: .3rem;
  transition: gap var(--transition);
}
.section-link:hover { gap: .6rem; }
.section-link[aria-label]::after { content: ' →'; }

/* ── NAV ──────────────────────────────────────────────────── */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  height: 62px;
}

.nav-logo {
  font-size: 1.3rem;
  font-weight: 900;
  letter-spacing: -.04em;
  color: var(--accent);
  flex-shrink: 0;
  margin-right: auto;
}
.nav-logo span { color: var(--text); }

.nav-links {
  display: flex;
  gap: .25rem;
  list-style: none;
}

.nav-links a {
  padding: .4rem .75rem;
  border-radius: 6px;
  font-size: .9rem;
  font-weight: 500;
  color: var(--muted);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a[aria-current="page"] {
  color: var(--text);
  background: var(--surface-2);
}

.nav-actions {
  display: flex;
  gap: .5rem;
  align-items: center;
}

.icon-btn {
  background: none;
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: .45rem .65rem;
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .85rem;
  font-weight: 600;
  transition: background var(--transition), border-color var(--transition);
}
.icon-btn:hover { background: var(--surface-2); border-color: var(--muted); }
.icon-btn .badge {
  background: var(--accent-2);
  color: #fff;
  border-radius: 99px;
  font-size: .65rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-inline: .3rem;
}

.nav-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  padding: .4rem;
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-menu-btn { display: flex; align-items: center; }
}

/* ── HERO ─────────────────────────────────────────────────── */
.hero {
  padding-block: 0;
  position: relative;
  overflow: hidden;
  min-height: clamp(400px, 60vh, 680px);
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,197,71,.12) 0%, transparent 65%),
    radial-gradient(ellipse 50% 70% at 20% 80%, rgba(224,92,92,.08) 0%, transparent 55%),
    linear-gradient(160deg, #131318 0%, #0d0d0f 100%);
}

.hero-grid-lines {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.03) 1px, transparent 1px);
  background-size: 48px 48px;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
  padding-block: 5rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: rgba(232,197,71,.12);
  border: 1px solid rgba(232,197,71,.3);
  color: var(--accent);
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: .35rem .85rem;
  border-radius: 99px;
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.2rem, 6vw, 4rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}

.hero-title .highlight {
  background: linear-gradient(90deg, var(--accent), #f0a843);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-desc {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 500px;
  margin-bottom: 2rem;
}

.hero-cta {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-primary {
  background: var(--accent);
  color: #000;
  font-weight: 700;
  font-size: .95rem;
  padding: .75rem 1.75rem;
  border-radius: var(--radius);
  border: 2px solid var(--accent);
  transition: opacity var(--transition), transform var(--transition);
}
.btn-primary:hover { opacity: .88; transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); }

.btn-secondary {
  background: transparent;
  color: var(--text);
  font-weight: 600;
  font-size: .95rem;
  padding: .75rem 1.75rem;
  border-radius: var(--radius);
  border: 2px solid var(--border);
  transition: border-color var(--transition), background var(--transition);
}
.btn-secondary:hover { border-color: var(--muted); background: var(--surface-2); }

.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 3rem;
  flex-wrap: wrap;
}
.stat-item { display: flex; flex-direction: column; gap: .1rem; }
.stat-value { font-size: 1.5rem; font-weight: 800; letter-spacing: -.03em; }
.stat-label { font-size: .78rem; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }

/* ── CATEGORIES BAR ───────────────────────────────────────── */
.categories {
  padding-block: 2rem;
  border-bottom: 1px solid var(--border);
}

.categories-list {
  display: flex;
  gap: .75rem;
  list-style: none;
  overflow-x: auto;
  padding-bottom: .25rem;
  scrollbar-width: none;
}
.categories-list::-webkit-scrollbar { display: none; }

.cat-chip {
  flex-shrink: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--muted);
  padding: .45rem 1.1rem;
  border-radius: 99px;
  font-size: .85rem;
  font-weight: 500;
  transition: all var(--transition);
  white-space: nowrap;
}
.cat-chip:hover,
.cat-chip[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #000;
  font-weight: 700;
}

/* ── PRODUCT GRID ─────────────────────────────────────────── */
.products-section { background: var(--bg); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--muted);
  box-shadow: 0 12px 40px rgba(0,0,0,.4);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--surface-2);
  overflow: hidden;
}

.product-img-placeholder {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  user-select: none;
  transition: transform var(--transition);
}
.product-card:hover .product-img-placeholder { transform: scale(1.05); }

.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  background: var(--accent-2);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 6px;
}
.product-badge.new { background: #3b82f6; }
.product-badge.sale { background: var(--accent-2); }

.product-wishlist {
  position: absolute;
  top: .75rem; right: .75rem;
  background: rgba(13,13,15,.7);
  border: 1px solid var(--border);
  color: var(--muted);
  width: 32px; height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: all var(--transition);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] {
  color: var(--accent-2);
  border-color: var(--accent-2);
  background: rgba(224,92,92,.15);
}

.product-body {
  padding: 1.1rem;
  display: flex;
  flex-direction: column;
  gap: .4rem;
  flex: 1;
}

.product-category {
  font-size: .72rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--muted);
  font-weight: 600;
}

.product-name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .8rem;
}
.stars { color: var(--accent); letter-spacing: .05em; }
.rating-count { color: var(--muted); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: .5rem;
  gap: .5rem;
}

.price-group { display: flex; align-items: baseline; gap: .4rem; }
.price-current { font-size: 1.15rem; font-weight: 800; letter-spacing: -.02em; }
.price-original { font-size: .85rem; color: var(--muted); text-decoration: line-through; }
.price-save { font-size: .72rem; font-weight: 700; color: var(--accent-2); }

.add-to-cart {
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text);
  padding: .45rem .9rem;
  border-radius: 8px;
  font-size: .82rem;
  font-weight: 600;
  white-space: nowrap;
  transition: background var(--transition), border-color var(--transition);
  flex-shrink: 0;
}
.add-to-cart:hover { background: var(--accent); border-color: var(--accent); color: #000; }

/* ── DEALS SECTION ────────────────────────────────────────── */
.deals-section { background: var(--surface); }

.deals-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

@media (max-width: 900px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card.featured { grid-column: span 2; }
}
@media (max-width: 560px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.featured { grid-column: span 1; }
}

.deal-card {
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 220px;
  border: 1px solid var(--border);
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover { transform: translateY(-3px); box-shadow: 0 16px 48px rgba(0,0,0,.5); }
.deal-card:focus-within { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius); }

.deal-card.featured { grid-row: span 2; min-height: 460px; }

.deal-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
}
.deal-card.featured .deal-bg { font-size: 10rem; }

.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.85) 0%, rgba(0,0,0,.2) 60%, transparent 100%);
}

.deal-content {
  position: relative;
  z-index: 1;
  padding: 1.25rem;
}

.deal-tag {
  display: inline-block;
  background: var(--accent-2);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 6px;
  margin-bottom: .6rem;
}
.deal-tag.gold { background: var(--accent); color: #000; }

.deal-title {
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: .35rem;
}
.deal-card.featured .deal-title { font-size: 1.6rem; }

.deal-subtitle { font-size: .85rem; color: rgba(240,240,244,.7); margin-bottom: .9rem; }

.deal-link {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.2);
  color: var(--text);
  padding: .45rem .9rem;
  border-radius: 8px;
  font-size: .82rem;
  font-weight: 600;
  transition: background var(--transition);
  backdrop-filter: blur(4px);
}
.deal-link:hover { background: rgba(255,255,255,.22); }

/* Countdown timer */
.countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: .9rem;
  align-items: center;
}
.countdown-label { font-size: .72rem; color: rgba(240,240,244,.6); text-transform: uppercase; letter-spacing: .06em; margin-right: .25rem; }
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(0,0,0,.4);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 6px;
  padding: .3rem .5rem;
  min-width: 40px;
}
.countdown-num { font-size: 1rem; font-weight: 800; line-height: 1; font-variant-numeric: tabular-nums; }
.countdown-sub { font-size: .58rem; color: rgba(240,240,244,.5); text-transform: uppercase; letter-spacing: .06em; }

/* ── EDITORIAL SECTION ────────────────────────────────────── */
.editorial-section { background: var(--bg); }

.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}

@media (max-width: 768px) { .editorial-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 480px) { .editorial-grid { grid-template-columns: 1fr; } }

.editorial-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), border-color var(--transition);
}
.editorial-card:hover { transform: translateY(-3px); border-color: var(--muted); }

.editorial-thumb {
  aspect-ratio: 16 / 9;
  background: var(--surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  position: relative;
  overflow: hidden;
}
.editorial-thumb-bg {
  position: absolute;
  inset: 0;
  opacity: .18;
}

.editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }

.editorial-tag {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
}

.editorial-title {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.35;
}

.editorial-excerpt {
  font-size: .87rem;
  color: var(--muted);
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: .5rem;
  font-size: .78rem;
  color: var(--muted);
  border-top: 1px solid var(--border);
  padding-top: .75rem;
}
.editorial-read-more {
  color: var(--accent);
  font-weight: 600;
  font-size: .8rem;
  display: flex;
  align-items: center;
  gap: .2rem;
  transition: gap var(--transition);
}
.editorial-card:hover .editorial-read-more { gap: .45rem; }

/* ── NEWSLETTER BANNER ────────────────────────────────────── */
.newsletter-section {
  padding-block: 3rem;
  background: var(--surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.newsletter-text h2 {
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .35rem;
}
.newsletter-text p { font-size: .9rem; color: var(--muted); }

.newsletter-form {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
}

.newsletter-input {
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text);
  padding: .7rem 1.1rem;
  border-radius: var(--radius);
  font-size: .9rem;
  min-width: 260px;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: var(--muted); }
.newsletter-input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgba(232,197,71,.15); }

/* ── FOOTER ───────────────────────────────────────────────── */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding-block: 3rem 1.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.8fr repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 2.5rem;
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

.footer-brand p { font-size: .87rem; color: var(--muted); margin-top: .75rem; max-width: 280px; line-height: 1.55; }

.footer-col h3 {
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 1rem;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: .55rem; }
.footer-col a { font-size: .87rem; color: var(--muted); transition: color var(--transition); }
.footer-col a:hover { color: var(--text); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  font-size: .8rem;
  color: var(--muted);
}

.footer-badges { display: flex; gap: .5rem; flex-wrap: wrap; }
.payment-badge {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: .3rem .6rem;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .04em;
}

/* ── Animations ───────────────────────────────────────────── */
@keyframes fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
.animate-in { animation: fade-up .5s ease both; }
.animate-in:nth-child(2) { animation-delay: .1s; }
.animate-in:nth-child(3) { animation-delay: .2s; }
.animate-in:nth-child(4) { animation-delay: .3s; }
.animate-in:nth-child(5) { animation-delay: .4s; }

/* ── Reduced motion ───────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ── App.js — React-style component functions ───────────────
   Each component is a function returning an HTML string.
   Mount point: #root
   ─────────────────────────────────────────────────────────── */

/* ── Data ──────────────────────────────────────────────────── */
const CATEGORIES = ['All', 'Apparel', 'Electronics', 'Home & Living', 'Footwear', 'Accessories', 'Sports', 'Beauty'];

const PRODUCTS = [
  {
    id: 1, name: 'Obsidian Bomber Jacket', category: 'Apparel',
    emoji: '🧥', price: 189, originalPrice: 249,
    rating: 4.8, reviews: 312, badge: 'sale', colors: ['#1a1a1a','#3b4a5a','#5a3b3b'],
  },
