*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0f;
  --surface:   #17171b;
  --surface-2: #222228;
  --border:    #2e2e38;
  --accent:    #e8c547;
  --accent-2:  #e05c5c;
  --text:      #f0f0f4;
  --muted:     #8888a0;
  --radius:    12px;
  --transition: 220ms ease;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; }

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px; left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: #000;
  padding: .5rem 1.25rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 700;
  z-index: 9999;
  white-space: nowrap;
}
.skip-link:focus { top: 0; }

/* ── Focus ring ───────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Layout helpers ───────────────────────────────────────── */
.container {
  width: min(1200px, 100%);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

section { padding-block: 4rem; }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-title {
  font-size: clamp(1.3rem, 3vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.section-link {
  font-size: .85rem;
  color: var(--accent);
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: .3rem;
  transition: gap var(--transition);
}
.section-link:hover { gap: .6rem; }
.section-link[aria-label]::after { content: ' →'; }

/* ── NAV ──────────────────────────────────────────────────── */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  height: 62px;
}

.nav-logo {
  font-size: 1.3rem;
  font-weight: 900;
  letter-spacing: -.04em;
  color: var(--accent);
  flex-shrink: 0;
  margin-right: auto;
}
.nav-logo span { color: var(--text); }

.nav-links {
  display: flex;
  gap: .25rem;
  list-style: none;
}

.nav-links a {
  padding: .4rem .75rem;
  border-radius: 6px;
  font-size: .9rem;
  font-weight: 500;
  color: var(--muted);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a[aria-current="page"] {
  color: var(--text);
  background: var(--surface-2);
}

.nav-actions {
  display: flex;
  gap: .5rem;
  align-items: center;
}

.icon-btn {
  background: none;
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: .45rem .65rem;
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .85rem;
  font-weight: 600;
  transition: background var(--transition), border-color var(--transition);
}
.icon-btn:hover { background: var(--surface-2); border-color: var(--muted); }
.icon-btn .badge {
  background: var(--accent-2);
  color: #fff;
  border-radius: 99px;
  font-size: .65rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-inline: .3rem;
}

.nav-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  padding: .4rem;
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-menu-btn { display: flex; align-items: center; }
}

/* ── HERO ─────────────────────────────────────────────────── */
.hero {
  padding-block: 0;
  position: relative;
  overflow: hidden;
  min-height: clamp(400px, 60vh, 680px);
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232,197,71,.12) 0%, transparent 65%),
    radial-gradient(ellipse 50% 70% at 20% 80%, rgba(224,92,92,.08) 0%, transparent 55%),
    linear-gradient(160deg, #131318 0%, #0d0d0f 100%);
}

.hero-grid-lines {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.03) 1px, transparent 1px);
  background-size: 48px 48px;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
  padding-block: 5rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: rgba(232,197,71,.12);
  border: 1px solid rgba(232,197,71,.3);
  color: var(--accent);
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .1em;
