}

.deal-tag {
  display: inline-block;
  background: var(--accent-2);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 6px;
  margin-bottom: .6rem;
}
