.editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }

.editorial-tag {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
}

.editorial-title {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.35;
}

.editorial-excerpt {
  font-size: .87rem;
