}

.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: .5rem;
  font-size: .78rem;
  color: var(--muted);
  border-top: 1px solid var(--border);
  padding-top: .75rem;
}
.editorial-read-more {
  color: var(--accent);
  font-weight: 600;
  font-size: .8rem;
  display: flex;
  align-items: center;
  gap: .2rem;
  transition: gap var(--transition);
}
.editorial-card:hover .editorial-read-more { gap: .45rem; }

/* ── NEWSLETTER BANNER ────────────────────────────────────── */
.newsletter-section {
  padding-block: 3rem;
  background: var(--surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.newsletter-text h2 {
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .35rem;
}
